// Illustrative ledger. Not connected to fee collectors or pool balances.
const mintLedger=[{token:3,value:620,time:'14:32',stage:'Added to pool'},{token:7,value:480,time:'13:48',stage:'Added to pool'},{token:3,value:350,time:'12:16',stage:'Added to pool'},{token:7,value:250,time:'11:41',stage:'Added to pool'},{token:5,value:180,time:'10:08',stage:'Awaiting graduation'},{token:1,value:120,time:'09:22',stage:'Awaiting graduation'}];
let mintPeriod='24h',mintAnimationPaused=matchMedia('(prefers-reduced-motion: reduce)').matches;const mintIntervals={'24h':1,'7d':7,'30d':30};
function enterMint(){modal.close();location.hash='mint';if(location.hash==='#mint')showMint()}
liquidity=enterMint;$('#engine').onclick=enterMint;$('#feesFooter').onclick=enterMint;$('#about').onclick=enterMint;$('.nav[data-page="liquidity"]').onclick=enterMint;
function showMint(){if(chartObserver){chartObserver.disconnect();chartObserver=null}homeMain.hidden=true;detailMain.hidden=false;document.title='The Mint — BlueMint';$$('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page==='liquidity'));const mult=mintIntervals[mintPeriod],allocated=2000*mult,added=1700*mult,waiting=300*mult;detailMain.innerHTML=`<div class="token-breadcrumb"><a href="#">← Back to discovery</a><span>/</span><span>The Mint</span><span class="mint-demo-pill">ILLUSTRATIVE DASHBOARD</span></div><section class="mint-hero"><div class="mint-hero-copy"><div class="mint-crest">♜ <span>THE LIQUIDITY TREASURY</span></div><h1>The Mint<span>Built coin<br>by coin.</span></h1><p>A home for deeper markets. A share of every eligible trade is earmarked for that token’s own liquidity.</p><div class="mint-hero-actions"><a href="#mintLedger" class="primary" id="mintLedgerLink">Open the ledger ↓</a><button class="text-btn" id="mintPolicy">The Mint’s charter </button></div><div class="mint-guarantees"><span>◈ USDC denominated</span><span>◈ No holder rewards</span></div></div><div class="mint-vault-stage"><div class="mint-vault-top"><span>VAULT / 001</span><span>ANIMATED CONCEPT</span></div><div class="mint-vault-media"><img id="mintVault" src="assets/mint-vault.${mintAnimationPaused?'png':'gif'}" alt="Pixel treasury safe opens, blue USDC coins fall inside, and the coin pile grows"><div class="vault-floor"></div></div><div class="mint-vault-bottom"><span><i></i> Accumulate. Pair. Deepen.</span></div><p class="vault-art-note">Visual metaphor only · vault animation does not represent custody or live balances</p></div></section><div class="mint-section-heading"><div><span class="eyebrow blue">THE RESERVE REPORT</span><h2>Every allocation, accounted for.</h2></div><div class="mint-periods">${['24h','7d','30d'].map(p=>`<button data-mint-period="${p}" class="${mintPeriod===p?'active':''}">${p}</button>`).join('')}</div></div><div class="mint-stats"><div><span>Liquidity allocation · sample</span><strong>${money(allocated)} <small>USDC</small></strong><p>0.75% of sample fee-assessed volume</p></div><div><span>Deployed capital · sample</span><strong>${money(added)} <small>USDC</small></strong><p>Original USDC budget used for buy + pair</p></div><div><span>Awaiting graduation · sample</span><strong>${money(waiting)} <small>USDC</small></strong><p>Allocated; not yet added to a pool</p></div><div><span>Markets in this report</span><strong>04 <small>TOKENS</small></strong><p>2 graduated · 2 on the curve</p></div></div><section class="mint-report-grid"><div class="mint-growth"><div class="mint-panel-heading"><h3>Depth takes commitment.</h3><span>CUMULATIVE SAMPLE ALLOCATION</span></div><div class="mint-growing-art"><picture><source media="(prefers-reduced-motion: reduce)" srcset="assets/how-growing.png"><img src="assets/how-growing.gif" alt="Blue-and-white pixel USDC chips stacking up, an illustration of growing liquidity"></picture><span>ILLUSTRATIVE LIQUIDITY GROWTH</span></div><div class="mint-chart-foot"><span>USDC allocated over selected sample period</span><b>${money(allocated)} USDC</b></div></div><div class="mint-split-panel"><span class="eyebrow blue">THE MINT’S CHARTER</span><h3>One fee.<br>Two destinations.</h3><div class="mint-split-visual"><span style="width:60%">60% LIQUIDITY</span><span style="width:40%">40% PLATFORM</span></div><div class="split"><span>Token’s liquidity allocation</span><b>0.75%</b></div><div class="split"><span>Launchpad treasury</span><b>0.50%</b></div><div class="split"><span>Launchpad subtotal</span><b>1.25%</b></div><p>Raydium fees are additional. Each token’s allocation stays separate; there is no shared token-liquidity pot.</p></div></section><section class="mint-token-panel"><div class="mint-panel-heading"><div><span class="eyebrow blue">TOKEN RESERVES</span><h3>Each market. Its own Mint.</h3></div><span>SAMPLE ALLOCATIONS · ${mintPeriod}</span></div><div class="mint-reserves">${[3,7,5,1].map(id=>{const t=tokens.find(t=>t.id===id),amount=mintLedger.filter(r=>r.token===id).reduce((n,r)=>n+r.value,0)*mult;return `<a href="#token/${id}" class="mint-reserve"><div class="token-top"><span class="avatar" style="--art:${t.art}">${esc(t.symbol)}</span><div><h3>${esc(t.name)}</h3><span class="ticker">${esc(t.ticker)} / USDC</span></div><span class="reserve-arrow"></span></div><strong>${money(amount)} <small>USDC</small></strong><div class="progress"><div style="width:${t.status==='graduated'?100:0}%"></div></div><p>${t.status==='graduated'?'Sample budget deployed':'Sample budget awaiting graduation'}</p></a>`}).join('')}</div></section><section class="mint-ledger" id="mintLedger"><div class="mint-panel-heading"><div><span class="eyebrow blue">THE PUBLIC LEDGER</span><h3>A record of every step.</h3></div><label class="mint-ledger-filter">Show <select id="mintFilter" aria-label="Filter sample ledger"><option value="all">All activity</option><option value="Added to pool">Added to pool</option><option value="Awaiting graduation">Awaiting graduation</option></select></label></div><div id="mintLedgerRows"></div><div class="mint-ledger-note">Demonstration entries only. Live transaction signatures and LP-lock receipts will appear after the on-chain integration is deployed.</div></section><div class="mint-cycle"><span>01 <b>Collect the allocation</b></span><i>→</i><span>02 <b>Buy tokens + retain USDC</b></span><i>→</i><span>03 <b>Add liquidity + lock LP</b></span></div><div class="mint-disclosure"><b>About this preview</b><p>The Mint is a proposed automated liquidity strategy. No fee collector, vault, buyback keeper or LP-lock contract is deployed. “Deployed capital” above is illustrative historical input, not current pool TVL or guaranteed backing. Added liquidity does not guarantee a price floor.</p></div>`;
$('#mintLedgerLink').onclick=e=>{e.preventDefault();$('#mintLedger').scrollIntoView({behavior:'smooth'})};$('#mintPolicy').onclick=()=>$('.mint-split-panel').scrollIntoView({behavior:'smooth'});$$('[data-mint-period]').forEach(b=>b.onclick=()=>{const scroll=window.scrollY;mintPeriod=b.dataset.mintPeriod;showMint();window.scrollTo(0,scroll)});$('#mintFilter').onchange=renderMintLedger;renderMintLedger()}
function renderMintLedger(){const filter=$('#mintFilter').value,m=mintIntervals[mintPeriod];$('#mintLedgerRows').innerHTML=`<div class="table-scroll"><table><thead><tr><th>Sample checkpoint</th><th>Token</th><th>Capital allocated · USDC</th><th>Stage</th><th>Record</th></tr></thead><tbody>${mintLedger.filter(r=>filter==='all'||r.stage===filter).map((r,i)=>{const t=tokens.find(t=>t.id===r.token);return `<tr><td>${r.time} UTC</td><td><a href="#token/${t.id}">${esc(t.ticker)} </a></td><td>${money(r.value*m)}</td><td><span class="mint-stage ${r.stage==='Added to pool'?'deployed':''}">${r.stage}</span></td><td><span class="demo-tag">DEMO · NO TRANSACTION</span></td></tr>`}).join('')}</tbody></table></div>`}
window.addEventListener('hashchange',()=>{if(location.hash!=='#mint')$$('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===view))});
